begin
for x in select value from jsonb_array_elements('[{"identity":"repo:https://github.com/karakeep-app/karakeep","slug":"karakeep-43e20952","name":"Karakeep","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Lưu được một ý tưởng hay chưa đủ — phải tìm lại được lúc cần viết.","description":"Karakeep, trước đây tên Hoarder, là ứng dụng lưu link, ghi chú, ảnh và PDF có hỗ trợ AI gắn thẻ, tóm tắt và tìm kiếm. Nó phục vụ đúng việc creator hay gặp: thấy một bài đáng tham khảo trên điện thoại nhưng đến lúc làm nội dung lại không nhớ đã lưu đâu. Có thể tự host hoặc dùng dịch vụ cloud của dự án.","long_description":"ĐIỂM NỔI BẬT\n• Gom bookmark thành danh sách, cộng tác và lưu đoạn đánh dấu đáng chú ý.\n• AI gắn thẻ/tóm tắt và tìm kiếm ngữ nghĩa; hỗ trợ mô hình local qua Ollama.\n• Extension trình duyệt, ứng dụng di động và thu thập từ RSS giúp đưa nguồn về cùng một nơi.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nLưu bài chính chủ, hình tham khảo và feedback người dùng cho một tool; xếp chúng vào cùng danh sách để dựng bài review có nguồn.\n\nBẮT ĐẦU\nXem demo chỉ đọc, sau đó chọn cloud hoặc hướng dẫn self-host; bật AI nếu thực sự cần và kiểm tra nơi dữ liệu được gửi.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nLưu trữ bài/ảnh/video không đồng nghĩa được phép tái xuất bản. Nội dung nhạy cảm trong bookmark có thể được gửi tới mô hình nếu bật tính năng AI.","canonical_url":"https://github.com/karakeep-app/karakeep","repository_url":"https://github.com/karakeep-app/karakeep","documentation_url":"https://raw.githubusercontent.com/karakeep-app/karakeep/main/README.md","owner_name":"karakeep-app","license":"AGPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":91,"categories":["research","content","social"],"primaryCategory":"research","selectionReason":"Phù hợp Research & Ý tưởng: Lưu được một ý tưởng hay chưa đủ — phải tìm lại được lúc cần viết. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Lưu được một ý tưởng hay chưa đủ — phải tìm lại được lúc cần viết.","highlights":["Gom bookmark thành danh sách, cộng tác và lưu đoạn đánh dấu đáng chú ý.","AI gắn thẻ/tóm tắt và tìm kiếm ngữ nghĩa; hỗ trợ mô hình local qua Ollama.","Extension trình duyệt, ứng dụng di động và thu thập từ RSS giúp đưa nguồn về cùng một nơi."],"example":"Lưu bài chính chủ, hình tham khảo và feedback người dùng cho một tool; xếp chúng vào cùng danh sách để dựng bài review có nguồn.","setup":"Xem demo chỉ đọc, sau đó chọn cloud hoặc hướng dẫn self-host; bật AI nếu thực sự cần và kiểm tra nơi dữ liệu được gửi.","limitations":"Lưu trữ bài/ảnh/video không đồng nghĩa được phép tái xuất bản. Nội dung nhạy cảm trong bookmark có thể được gửi tới mô hình nếu bật tính năng AI.","github":{"stars":28761,"forks":1474,"observedAt":"2026-09-03T16:07:56.087Z","url":"https://github.com/karakeep-app/karakeep","pushedAt":"2026-08-31T22:52:10Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/karakeep-app/karakeep/main/README.md","observedAt":"2026-09-03T16:09:36.459Z","sha256":"ecc3cd2eb9a38a919bea7ccb71cd9e83c2dfc01d03601a70879433e0d3f326d9"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"karakeep-app/karakeep:metadata","source_url":"https://github.com/karakeep-app/karakeep","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Adanny-avila%2FLibreChat%20repo%3Aassafelovic%2Fgpt-researcher%20repo%3Abytedance%2Fdeer-flow%20repo%3Aitzcrazykns%2Fvane%20repo%3Akhoj-ai%2Fkhoj%20repo%3Akarakeep-app%2Fkarakeep%20repo%3AFreshRSS%2FFreshRSS%20repo%3ADIYgod%2FRSSHub&per_page=100","stars":28761,"forks":1474,"license":"AGPL-3.0"},"fetched_at":"2026-09-03T16:07:56.087Z"},{"source_type":"github","source_identifier":"karakeep-app/karakeep:readme:ecc3cd2eb9a38a919bea7ccb71cd9e83c2dfc01d03601a70879433e0d3f326d9","source_url":"https://raw.githubusercontent.com/karakeep-app/karakeep/main/README.md","raw_metadata":{"sha256":"ecc3cd2eb9a38a919bea7ccb71cd9e83c2dfc01d03601a70879433e0d3f326d9","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:36.459Z"}],"expected":null},{"identity":"repo:https://github.com/freshrss/freshrss","slug":"freshrss-5fd62137","name":"FreshRSS","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một hộp thư cho nguồn tin, không bị feed mạng xã hội quyết định thứ bạn đọc.","description":"FreshRSS là trình gom RSS tự host, có phân loại bằng tag, hỗ trợ nhiều người dùng và API cho ứng dụng đọc trên điện thoại. Creator có thể dùng nó để theo dõi tác giả, blog và cập nhật sản phẩm theo nguồn mình chọn. Nó không tự viết nội dung; giá trị là giúp việc đọc và chọn đề tài có hệ thống hơn.","long_description":"ĐIỂM NỔI BẬT\n• Đọc feed tập trung, gắn thẻ và tổ chức nguồn theo nhu cầu.\n• Nhận cập nhật từ nguồn hỗ trợ WebSub; có thể đọc một số nguồn không có feed qua cấu hình riêng.\n• Chia sẻ phần tuyển chọn qua HTML, RSS hoặc OPML.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nLập nhóm nguồn về video, social và SEO, đọc theo ngách rồi chọn vài thay đổi đáng chú ý cho bản tin hàng tuần.\n\nBẮT ĐẦU\nDùng bản phát hành ổn định và hướng dẫn Docker/hosting hoặc cài đặt chính chủ. Không nhầm nhánh edge với bản ổn định.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nPhải vận hành máy chủ nếu tự host. Chất lượng phụ thuộc nguồn bạn theo dõi; dữ liệu bài và ngày xuất bản từ feed cần kiểm tra lại khi dùng làm tin.","canonical_url":"https://github.com/FreshRSS/FreshRSS","repository_url":"https://github.com/FreshRSS/FreshRSS","documentation_url":"https://raw.githubusercontent.com/FreshRSS/FreshRSS/edge/README.md","owner_name":"FreshRSS","license":"AGPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":92,"categories":["research","content"],"primaryCategory":"research","selectionReason":"Phù hợp Research & Ý tưởng: Một hộp thư cho nguồn tin, không bị feed mạng xã hội quyết định thứ bạn đọc. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một hộp thư cho nguồn tin, không bị feed mạng xã hội quyết định thứ bạn đọc.","highlights":["Đọc feed tập trung, gắn thẻ và tổ chức nguồn theo nhu cầu.","Nhận cập nhật từ nguồn hỗ trợ WebSub; có thể đọc một số nguồn không có feed qua cấu hình riêng.","Chia sẻ phần tuyển chọn qua HTML, RSS hoặc OPML."],"example":"Lập nhóm nguồn về video, social và SEO, đọc theo ngách rồi chọn vài thay đổi đáng chú ý cho bản tin hàng tuần.","setup":"Dùng bản phát hành ổn định và hướng dẫn Docker/hosting hoặc cài đặt chính chủ. Không nhầm nhánh edge với bản ổn định.","limitations":"Phải vận hành máy chủ nếu tự host. Chất lượng phụ thuộc nguồn bạn theo dõi; dữ liệu bài và ngày xuất bản từ feed cần kiểm tra lại khi dùng làm tin.","github":{"stars":15921,"forks":1266,"observedAt":"2026-09-03T16:07:56.087Z","url":"https://github.com/FreshRSS/FreshRSS","pushedAt":"2026-09-03T06:57:41Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/FreshRSS/FreshRSS/edge/README.md","observedAt":"2026-09-03T16:09:37.104Z","sha256":"e7cf5f71bc5f5d9a19eb4b620dbdbd0c70d4cf9cd8425c350df7e28e348810c7"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"FreshRSS/FreshRSS:metadata","source_url":"https://github.com/FreshRSS/FreshRSS","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Adanny-avila%2FLibreChat%20repo%3Aassafelovic%2Fgpt-researcher%20repo%3Abytedance%2Fdeer-flow%20repo%3Aitzcrazykns%2Fvane%20repo%3Akhoj-ai%2Fkhoj%20repo%3Akarakeep-app%2Fkarakeep%20repo%3AFreshRSS%2FFreshRSS%20repo%3ADIYgod%2FRSSHub&per_page=100","stars":15921,"forks":1266,"license":"AGPL-3.0"},"fetched_at":"2026-09-03T16:07:56.087Z"},{"source_type":"github","source_identifier":"FreshRSS/FreshRSS:readme:e7cf5f71bc5f5d9a19eb4b620dbdbd0c70d4cf9cd8425c350df7e28e348810c7","source_url":"https://raw.githubusercontent.com/FreshRSS/FreshRSS/edge/README.md","raw_metadata":{"sha256":"e7cf5f71bc5f5d9a19eb4b620dbdbd0c70d4cf9cd8425c350df7e28e348810c7","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:37.104Z"}],"expected":null},{"identity":"repo:https://github.com/langgenius/dify","slug":"dify-4ccdcdc6","name":"Dify","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Đưa tài liệu thương hiệu vào một trợ lý nội dung có workflow và lịch sử kiểm tra.","description":"Dify là nền tảng xây ứng dụng AI bằng canvas, prompt và pipeline tri thức. Nó phù hợp tạo trợ lý dựa trên tài liệu của team, kết nối nhiều model rồi kiểm tra log để chỉnh chất lượng. Đây là công cụ xây quy trình, không tự biến dữ liệu chưa xác minh thành sự thật.","long_description":"ĐIỂM NỔI BẬT\n• Canvas workflow và giao diện thử prompt/model.\n• Nạp và truy hồi nội dung từ tài liệu cho ứng dụng AI.\n• Có agent/tool, quan sát log và API tích hợp.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nXây trợ lý gợi ý kịch bản dựa trên guideline thương hiệu, yêu cầu trích nguồn và để biên tập viên duyệt.\n\nBẮT ĐẦU\nDùng cloud hoặc Docker Compose theo tài liệu, cấu hình model và tập tài liệu được phép.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nGiấy phép Dify dựa trên Apache nhưng có điều kiện bổ sung. Self-host không giữ dữ liệu local nếu gọi cloud model; cần kiểm tra câu trả lời và phân quyền tài liệu.","canonical_url":"https://github.com/langgenius/dify","repository_url":"https://github.com/langgenius/dify","documentation_url":"https://raw.githubusercontent.com/langgenius/dify/main/README.md","owner_name":"langgenius","license":"Dify Open Source License, dựa trên Apache-2.0 kèm điều kiện bổ sung.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":93,"categories":["automation","content","research"],"primaryCategory":"automation","selectionReason":"Phù hợp Tự động hóa: Đưa tài liệu thương hiệu vào một trợ lý nội dung có workflow và lịch sử kiểm tra. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Đưa tài liệu thương hiệu vào một trợ lý nội dung có workflow và lịch sử kiểm tra.","highlights":["Canvas workflow và giao diện thử prompt/model.","Nạp và truy hồi nội dung từ tài liệu cho ứng dụng AI.","Có agent/tool, quan sát log và API tích hợp."],"example":"Xây trợ lý gợi ý kịch bản dựa trên guideline thương hiệu, yêu cầu trích nguồn và để biên tập viên duyệt.","setup":"Dùng cloud hoặc Docker Compose theo tài liệu, cấu hình model và tập tài liệu được phép.","limitations":"Giấy phép Dify dựa trên Apache nhưng có điều kiện bổ sung. Self-host không giữ dữ liệu local nếu gọi cloud model; cần kiểm tra câu trả lời và phân quyền tài liệu.","github":{"stars":154339,"forks":24398,"observedAt":"2026-09-03T16:09:14.057Z","url":"https://github.com/langgenius/dify","pushedAt":"2026-09-03T15:38:21Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/langgenius/dify/main/README.md","observedAt":"2026-09-03T16:10:47.764Z","sha256":"51647e1180794278e006c7e1925eec056d5b68a036893143849ef83ad695e7e2"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"langgenius/dify:metadata","source_url":"https://github.com/langgenius/dify","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Alanggenius%2Fdify%20repo%3AFlowiseAI%2FFlowise%20repo%3Asimstudioai%2Fsim%20repo%3Akestra-io%2Fkestra%20repo%3Aopenai%2Fcodex%20repo%3Agoogle-gemini%2Fgemini-cli%20repo%3Aanthropics%2Fclaude-code%20repo%3Abitwarden%2Fclients&per_page=100","stars":154339,"forks":24398,"license":"NOASSERTION"},"fetched_at":"2026-09-03T16:09:14.057Z"},{"source_type":"github","source_identifier":"langgenius/dify:readme:51647e1180794278e006c7e1925eec056d5b68a036893143849ef83ad695e7e2","source_url":"https://raw.githubusercontent.com/langgenius/dify/main/README.md","raw_metadata":{"sha256":"51647e1180794278e006c7e1925eec056d5b68a036893143849ef83ad695e7e2","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:47.764Z"}],"expected":null},{"identity":"repo:https://github.com/browser-use/browser-use","slug":"browser-use-26afa42b","name":"Browser Use","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Những thao tác web lặp lại có thể giao cho agent — nhưng nút đăng cuối cùng vẫn nên có người kiểm soát.","description":"Browser Use cho phép AI mở trang, bấm, nhập liệu và thao tác trình duyệt. Dự án có đường dùng qua agent/CLI và thư viện Python cho quy trình lập trình. Với creator, nó có thể hỗ trợ thu thập thông tin hoặc chuẩn bị thao tác đăng tải; không nên cấp toàn quyền tài khoản chỉ vì một demo chạy tốt.","long_description":"ĐIỂM NỔI BẬT\n• Điều khiển trình duyệt theo yêu cầu bằng ngôn ngữ tự nhiên.\n• Có ví dụ trích dữ liệu, điền biểu mẫu và làm việc trên website.\n• Phân biệt agent nguồn mở chạy tại máy với dịch vụ cloud có khả năng và chi phí riêng.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nYêu cầu agent thu thập các trường thông tin công khai của tool rồi trình lại bảng nguồn; nếu dùng cho upload, dừng trước bước xuất bản để tự kiểm tra.\n\nBẮT ĐẦU\nTheo Quick Start cho agent hoặc thư viện Python; cấu hình mô hình, chọn trình duyệt và giới hạn các thao tác được phép.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCó thể bấm nhầm hoặc gặp giao diện thay đổi. Bảo vệ phiên đăng nhập; không dùng để vượt hạn chế truy cập, gửi spam hay đăng nội dung chưa duyệt. Tính năng cloud không mặc định có trong bản nguồn mở.","canonical_url":"https://github.com/browser-use/browser-use","repository_url":"https://github.com/browser-use/browser-use","documentation_url":"https://raw.githubusercontent.com/browser-use/browser-use/main/README.md","owner_name":"browser-use","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":94,"categories":["automation","research","social"],"primaryCategory":"automation","selectionReason":"Phù hợp Tự động hóa: Những thao tác web lặp lại có thể giao cho agent — nhưng nút đăng cuối cùng vẫn nên có người kiểm soát. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Những thao tác web lặp lại có thể giao cho agent — nhưng nút đăng cuối cùng vẫn nên có người kiểm soát.","highlights":["Điều khiển trình duyệt theo yêu cầu bằng ngôn ngữ tự nhiên.","Có ví dụ trích dữ liệu, điền biểu mẫu và làm việc trên website.","Phân biệt agent nguồn mở chạy tại máy với dịch vụ cloud có khả năng và chi phí riêng."],"example":"Yêu cầu agent thu thập các trường thông tin công khai của tool rồi trình lại bảng nguồn; nếu dùng cho upload, dừng trước bước xuất bản để tự kiểm tra.","setup":"Theo Quick Start cho agent hoặc thư viện Python; cấu hình mô hình, chọn trình duyệt và giới hạn các thao tác được phép.","limitations":"Có thể bấm nhầm hoặc gặp giao diện thay đổi. Bảo vệ phiên đăng nhập; không dùng để vượt hạn chế truy cập, gửi spam hay đăng nội dung chưa duyệt. Tính năng cloud không mặc định có trong bản nguồn mở.","github":{"stars":112172,"forks":12333,"observedAt":"2026-09-03T16:08:02.616Z","url":"https://github.com/browser-use/browser-use","pushedAt":"2026-09-03T16:01:11Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/browser-use/browser-use/main/README.md","observedAt":"2026-09-03T16:09:38.554Z","sha256":"d71c156c2358b71cd764ef3d752ed18a9718e8ffd3184872b49ff91c447c6241"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"browser-use/browser-use:metadata","source_url":"https://github.com/browser-use/browser-use","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Amendableai%2Ffirecrawl%20repo%3Aunclecode%2Fcrawl4ai%20repo%3Abrowser-use%2Fbrowser-use%20repo%3Ajina-ai%2Freader%20repo%3Amicrosoft%2Fmarkitdown%20repo%3Ahamidteimour%2Fseo-audit-skill%20repo%3AAgriciDaniel%2Fclaude-seo%20repo%3Aonur-genc%2Fseo-mcp&per_page=100","stars":112172,"forks":12333,"license":"MIT"},"fetched_at":"2026-09-03T16:08:02.616Z"},{"source_type":"github","source_identifier":"browser-use/browser-use:readme:d71c156c2358b71cd764ef3d752ed18a9718e8ffd3184872b49ff91c447c6241","source_url":"https://raw.githubusercontent.com/browser-use/browser-use/main/README.md","raw_metadata":{"sha256":"d71c156c2358b71cd764ef3d752ed18a9718e8ffd3184872b49ff91c447c6241","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:38.554Z"}],"expected":"620a3d83-5588-4ef2-8b74-c9404e70e834"},{"identity":"repo:https://github.com/simstudioai/sim","slug":"sim-49547a83","name":"Sim","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Gom flow, file và tri thức của team vào một workspace để vận hành các bước AI.","description":"Sim cung cấp nơi xây, triển khai và theo dõi agent/workflow bằng giao diện, hội thoại hoặc code. Các bảng, file và knowledge ở cùng workspace giúp tổ chức quy trình nội dung theo dữ liệu, thay vì nối nhiều tác vụ không biết đang ở bước nào.","long_description":"ĐIỂM NỔI BẬT\n• Builder kết nối model và dịch vụ bên ngoài.\n• Tập trung table, file và knowledge trong workspace.\n• Theo dõi run, log, lịch và hoạt động workflow.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nLưu brief trong bảng, tạo bản nháp từ tài liệu đã duyệt rồi theo dõi trạng thái từng bài.\n\nBẮT ĐẦU\nSelf-host cần Node và Docker theo README; wizard tạo môi trường và cấu hình các khả năng tùy chọn.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nMột số dịch vụ như Chat được Sim quản lý; không coi self-host là hoàn toàn offline. Sao lưu dữ liệu và giữ khóa kín; không dùng thao tác reset khi chưa hiểu dữ liệu sẽ mất.","canonical_url":"https://github.com/simstudioai/sim","repository_url":"https://github.com/simstudioai/sim","documentation_url":"https://raw.githubusercontent.com/simstudioai/sim/main/README.md","owner_name":"simstudioai","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":95,"categories":["automation","content","research"],"primaryCategory":"automation","selectionReason":"Phù hợp Tự động hóa: Gom flow, file và tri thức của team vào một workspace để vận hành các bước AI. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Gom flow, file và tri thức của team vào một workspace để vận hành các bước AI.","highlights":["Builder kết nối model và dịch vụ bên ngoài.","Tập trung table, file và knowledge trong workspace.","Theo dõi run, log, lịch và hoạt động workflow."],"example":"Lưu brief trong bảng, tạo bản nháp từ tài liệu đã duyệt rồi theo dõi trạng thái từng bài.","setup":"Self-host cần Node và Docker theo README; wizard tạo môi trường và cấu hình các khả năng tùy chọn.","limitations":"Một số dịch vụ như Chat được Sim quản lý; không coi self-host là hoàn toàn offline. Sao lưu dữ liệu và giữ khóa kín; không dùng thao tác reset khi chưa hiểu dữ liệu sẽ mất.","github":{"stars":29532,"forks":3805,"observedAt":"2026-09-03T16:09:14.057Z","url":"https://github.com/simstudioai/sim","pushedAt":"2026-09-03T16:08:48Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/simstudioai/sim/main/README.md","observedAt":"2026-09-03T16:10:51.957Z","sha256":"923c11452288163cd65c3197b4f3af400030556ebcae2f03bc73a331f183ec08"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"simstudioai/sim:metadata","source_url":"https://github.com/simstudioai/sim","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Alanggenius%2Fdify%20repo%3AFlowiseAI%2FFlowise%20repo%3Asimstudioai%2Fsim%20repo%3Akestra-io%2Fkestra%20repo%3Aopenai%2Fcodex%20repo%3Agoogle-gemini%2Fgemini-cli%20repo%3Aanthropics%2Fclaude-code%20repo%3Abitwarden%2Fclients&per_page=100","stars":29532,"forks":3805,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:09:14.057Z"},{"source_type":"github","source_identifier":"simstudioai/sim:readme:923c11452288163cd65c3197b4f3af400030556ebcae2f03bc73a331f183ec08","source_url":"https://raw.githubusercontent.com/simstudioai/sim/main/README.md","raw_metadata":{"sha256":"923c11452288163cd65c3197b4f3af400030556ebcae2f03bc73a331f183ec08","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:51.957Z"}],"expected":null},{"identity":"repo:https://github.com/activepieces/activepieces","slug":"activepieces-aff7fd90","name":"Activepieces","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Tự động hóa các việc nhỏ quanh content bằng flow nhìn được và có bước duyệt.","description":"Activepieces là nền tảng automation với các khối tích hợp gọi là pieces. Có builder trực quan cho người ít code và khả năng mở rộng cho người có kỹ thuật. Creator có thể nối bảng kế hoạch, RSS, AI và thông báo mà không tự viết mọi kết nối từ đầu.","long_description":"ĐIỂM NỔI BẬT\n• Flow có loop, nhánh, retry và phiên bản.\n• Có input qua form/chat và bước chờ người duyệt.\n• Các piece có thể dùng trong hệ sinh thái MCP theo README.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nNhận đề xuất bài từ form, thêm nguồn và tạo bản nháp trong bảng duyệt của team.\n\nBẮT ĐẦU\nChọn Community/self-host hoặc dịch vụ phù hợp, cấp quyền từng kết nối và thử bằng dữ liệu mẫu.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCommunity Edition MIT nhưng enterprise có Commercial License. Không mặc định mọi tích hợp hỗ trợ toàn bộ thao tác của nền tảng; giữ kiểm soát chống gửi/đăng trùng.","canonical_url":"https://github.com/activepieces/activepieces","repository_url":"https://github.com/activepieces/activepieces","documentation_url":"https://raw.githubusercontent.com/activepieces/activepieces/main/README.md","owner_name":"activepieces","license":"Community Edition MIT; các tính năng enterprise có Commercial License.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":96,"categories":["automation","social","content"],"primaryCategory":"automation","selectionReason":"Phù hợp Tự động hóa: Tự động hóa các việc nhỏ quanh content bằng flow nhìn được và có bước duyệt. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Tự động hóa các việc nhỏ quanh content bằng flow nhìn được và có bước duyệt.","highlights":["Flow có loop, nhánh, retry và phiên bản.","Có input qua form/chat và bước chờ người duyệt.","Các piece có thể dùng trong hệ sinh thái MCP theo README."],"example":"Nhận đề xuất bài từ form, thêm nguồn và tạo bản nháp trong bảng duyệt của team.","setup":"Chọn Community/self-host hoặc dịch vụ phù hợp, cấp quyền từng kết nối và thử bằng dữ liệu mẫu.","limitations":"Community Edition MIT nhưng enterprise có Commercial License. Không mặc định mọi tích hợp hỗ trợ toàn bộ thao tác của nền tảng; giữ kiểm soát chống gửi/đăng trùng.","github":{"stars":24213,"forks":4136,"observedAt":"2026-09-03T16:09:07.643Z","url":"https://github.com/activepieces/activepieces","pushedAt":"2026-09-03T15:53:17Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/activepieces/activepieces/main/README.md","observedAt":"2026-09-03T16:10:45.667Z","sha256":"cd713ed6ae78214e2a54266541df2b8c1de6163312dd499a83d59a930065ed1b"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"activepieces/activepieces:metadata","source_url":"https://github.com/activepieces/activepieces","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Apresenton%2Fpresenton%20repo%3Amarp-team%2Fmarp%20repo%3Anextlevelbuilder%2Fui-ux-pro-max-skill%20repo%3Apbakaus%2Fimpeccable%20repo%3Aleonxlnx%2Ftaste-skill%20repo%3Ashadcn-ui%2Fui%20repo%3An8n-io%2Fn8n%20repo%3Aactivepieces%2Factivepieces&per_page=100","stars":24213,"forks":4136,"license":"NOASSERTION"},"fetched_at":"2026-09-03T16:09:07.643Z"},{"source_type":"github","source_identifier":"activepieces/activepieces:readme:cd713ed6ae78214e2a54266541df2b8c1de6163312dd499a83d59a930065ed1b","source_url":"https://raw.githubusercontent.com/activepieces/activepieces/main/README.md","raw_metadata":{"sha256":"cd713ed6ae78214e2a54266541df2b8c1de6163312dd499a83d59a930065ed1b","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:45.667Z"}],"expected":null},{"identity":"repo:https://github.com/anthropics/claude-code","slug":"claude-code-3b3c0687","name":"Claude Code","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một trợ lý kỹ thuật để giúp bạn chỉnh project và nối các bước của video kit.","description":"Claude Code là coding agent của Anthropic, làm việc với codebase và công cụ qua ngôn ngữ tự nhiên. Windi giữ mục này trong nhóm kỹ thuật giới hạn vì nó giúp creator thiết lập hoặc sửa workflow có code, không phải vì mọi người dùng đều cần học lập trình.","long_description":"ĐIỂM NỔI BẬT\n• Đọc, giải thích và hỗ trợ thay đổi code trong project.\n• Hỗ trợ các công việc thường ngày và Git qua terminal/IDE.\n• Repo có plugin mở rộng cùng đường dẫn tài liệu chính chủ.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nNhờ agent giải thích cấu trúc video kit và sửa đường dẫn media trong bản sao project, kiểm tra thay đổi trước khi chạy.\n\nBẮT ĐẦU\nTheo phương thức cài hiện được Anthropic khuyến nghị; README đã đánh dấu cách npm cũ là deprecated.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nĐây là repo chính chủ nhưng không đồng nghĩa toàn bộ sản phẩm là mã nguồn mở. Cần tài khoản/quyền dịch vụ phù hợp và kiểm soát lệnh, file, credential agent được phép dùng.","canonical_url":"https://github.com/anthropics/claude-code","repository_url":"https://github.com/anthropics/claude-code","documentation_url":"https://raw.githubusercontent.com/anthropics/claude-code/main/README.md","owner_name":"anthropics","license":"Điều khoản Anthropic/giấy phép từng phần; không gọi toàn sản phẩm là MIT hoặc Apache.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":97,"categories":["tech"],"primaryCategory":"tech","selectionReason":"Phù hợp Tech & Bảo mật: Một trợ lý kỹ thuật để giúp bạn chỉnh project và nối các bước của video kit. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một trợ lý kỹ thuật để giúp bạn chỉnh project và nối các bước của video kit.","highlights":["Đọc, giải thích và hỗ trợ thay đổi code trong project.","Hỗ trợ các công việc thường ngày và Git qua terminal/IDE.","Repo có plugin mở rộng cùng đường dẫn tài liệu chính chủ."],"example":"Nhờ agent giải thích cấu trúc video kit và sửa đường dẫn media trong bản sao project, kiểm tra thay đổi trước khi chạy.","setup":"Theo phương thức cài hiện được Anthropic khuyến nghị; README đã đánh dấu cách npm cũ là deprecated.","limitations":"Đây là repo chính chủ nhưng không đồng nghĩa toàn bộ sản phẩm là mã nguồn mở. Cần tài khoản/quyền dịch vụ phù hợp và kiểm soát lệnh, file, credential agent được phép dùng.","github":{"stars":143909,"forks":23002,"observedAt":"2026-09-03T16:09:14.057Z","url":"https://github.com/anthropics/claude-code","pushedAt":"2026-09-02T22:33:51Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/anthropics/claude-code/main/README.md","observedAt":"2026-09-03T16:10:48.542Z","sha256":"aa0d8b80ac083e1591be0789273f447058cc9187b4331634a5614155da27778d"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"anthropics/claude-code:metadata","source_url":"https://github.com/anthropics/claude-code","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Alanggenius%2Fdify%20repo%3AFlowiseAI%2FFlowise%20repo%3Asimstudioai%2Fsim%20repo%3Akestra-io%2Fkestra%20repo%3Aopenai%2Fcodex%20repo%3Agoogle-gemini%2Fgemini-cli%20repo%3Aanthropics%2Fclaude-code%20repo%3Abitwarden%2Fclients&per_page=100","stars":143909,"forks":23002,"license":null},"fetched_at":"2026-09-03T16:09:14.057Z"},{"source_type":"github","source_identifier":"anthropics/claude-code:readme:aa0d8b80ac083e1591be0789273f447058cc9187b4331634a5614155da27778d","source_url":"https://raw.githubusercontent.com/anthropics/claude-code/main/README.md","raw_metadata":{"sha256":"aa0d8b80ac083e1591be0789273f447058cc9187b4331634a5614155da27778d","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:48.542Z"}],"expected":null},{"identity":"repo:https://github.com/openai/codex","slug":"codex-cli-324831eb","name":"Codex CLI","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Dùng ngôn ngữ tự nhiên để làm việc với project local, thay vì tự nhớ mọi lệnh.","description":"Codex CLI là coding agent của OpenAI chạy trên máy. Nó là phần mã nguồn CLI, cần phân biệt với app desktop và dịch vụ cloud được README dẫn riêng. Creator có workflow bằng code có thể dùng để hỗ trợ thiết lập, đọc cấu trúc và chỉnh project.","long_description":"ĐIỂM NỔI BẬT\n• Có CLI local và binary theo hệ điều hành/kiến trúc.\n• Có cách đăng nhập tài khoản được hỗ trợ hoặc cấu hình API.\n• Repo CLI phát hành Apache-2.0 với tài liệu cài và đóng góp.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nMở bản sao video kit, yêu cầu giải thích file cấu hình và chuẩn bị thay nội dung cho dự án của bạn.\n\nBẮT ĐẦU\nDùng cách cài chính chủ đúng hệ điều hành, đăng nhập và kiểm tra quyền truy cập workspace.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nGiấy phép CLI không bao gồm chi phí model hay mọi quyền của dịch vụ. Agent có thể sửa/chạy code; đọc thay đổi, không đưa khóa vào prompt hay repo công khai.","canonical_url":"https://github.com/openai/codex","repository_url":"https://github.com/openai/codex","documentation_url":"https://raw.githubusercontent.com/openai/codex/main/README.md","owner_name":"openai","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":98,"categories":["tech"],"primaryCategory":"tech","selectionReason":"Phù hợp Tech & Bảo mật: Dùng ngôn ngữ tự nhiên để làm việc với project local, thay vì tự nhớ mọi lệnh. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Dùng ngôn ngữ tự nhiên để làm việc với project local, thay vì tự nhớ mọi lệnh.","highlights":["Có CLI local và binary theo hệ điều hành/kiến trúc.","Có cách đăng nhập tài khoản được hỗ trợ hoặc cấu hình API.","Repo CLI phát hành Apache-2.0 với tài liệu cài và đóng góp."],"example":"Mở bản sao video kit, yêu cầu giải thích file cấu hình và chuẩn bị thay nội dung cho dự án của bạn.","setup":"Dùng cách cài chính chủ đúng hệ điều hành, đăng nhập và kiểm tra quyền truy cập workspace.","limitations":"Giấy phép CLI không bao gồm chi phí model hay mọi quyền của dịch vụ. Agent có thể sửa/chạy code; đọc thay đổi, không đưa khóa vào prompt hay repo công khai.","github":{"stars":121209,"forks":18571,"observedAt":"2026-09-03T16:09:14.057Z","url":"https://github.com/openai/codex","pushedAt":"2026-09-03T15:14:24Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/openai/codex/main/README.md","observedAt":"2026-09-03T16:10:49.332Z","sha256":"ba4e1f69ff48386e72a9c5e1edaf76aad64a475c2d51af79ccba6d1128261ba7"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"openai/codex:metadata","source_url":"https://github.com/openai/codex","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Alanggenius%2Fdify%20repo%3AFlowiseAI%2FFlowise%20repo%3Asimstudioai%2Fsim%20repo%3Akestra-io%2Fkestra%20repo%3Aopenai%2Fcodex%20repo%3Agoogle-gemini%2Fgemini-cli%20repo%3Aanthropics%2Fclaude-code%20repo%3Abitwarden%2Fclients&per_page=100","stars":121209,"forks":18571,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:09:14.057Z"},{"source_type":"github","source_identifier":"openai/codex:readme:ba4e1f69ff48386e72a9c5e1edaf76aad64a475c2d51af79ccba6d1128261ba7","source_url":"https://raw.githubusercontent.com/openai/codex/main/README.md","raw_metadata":{"sha256":"ba4e1f69ff48386e72a9c5e1edaf76aad64a475c2d51af79ccba6d1128261ba7","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:49.332Z"}],"expected":null},{"identity":"repo:https://github.com/google-gemini/gemini-cli","slug":"gemini-cli-35b911ef","name":"Gemini CLI","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một agent terminal khác để nghiên cứu và hỗ trợ sửa workflow có code.","description":"Gemini CLI đưa model Gemini vào môi trường dòng lệnh với công cụ file, shell, web và MCP. Windi giữ nó như lựa chọn kỹ thuật thay thế, không xếp thành hàng chục tool nền tảng lấn át nhu cầu creator.","long_description":"ĐIỂM NỔI BẬT\n• Đọc/sửa code và xử lý input đa phương thức theo khả năng model.\n• Có Google Search grounding, đọc web và công cụ file/shell.\n• Có MCP, context theo project và chế độ chạy trong script.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nNhờ agent tìm tài liệu chính chủ rồi giải thích cách thay input trong một workflow video thử nghiệm.\n\nBẮT ĐẦU\nChọn bản stable và phương thức xác thực phù hợp từ tài liệu Google.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nQuota/model có thể thay đổi theo tài khoản; không quảng cáo miễn phí vô hạn. Preview/nightly chưa được kiểm tra như stable, và kết quả tìm kiếm vẫn phải đối chiếu nguồn.","canonical_url":"https://github.com/google-gemini/gemini-cli","repository_url":"https://github.com/google-gemini/gemini-cli","documentation_url":"https://raw.githubusercontent.com/google-gemini/gemini-cli/main/README.md","owner_name":"google-gemini","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":99,"categories":["tech"],"primaryCategory":"tech","selectionReason":"Phù hợp Tech & Bảo mật: Một agent terminal khác để nghiên cứu và hỗ trợ sửa workflow có code. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một agent terminal khác để nghiên cứu và hỗ trợ sửa workflow có code.","highlights":["Đọc/sửa code và xử lý input đa phương thức theo khả năng model.","Có Google Search grounding, đọc web và công cụ file/shell.","Có MCP, context theo project và chế độ chạy trong script."],"example":"Nhờ agent tìm tài liệu chính chủ rồi giải thích cách thay input trong một workflow video thử nghiệm.","setup":"Chọn bản stable và phương thức xác thực phù hợp từ tài liệu Google.","limitations":"Quota/model có thể thay đổi theo tài khoản; không quảng cáo miễn phí vô hạn. Preview/nightly chưa được kiểm tra như stable, và kết quả tìm kiếm vẫn phải đối chiếu nguồn.","github":{"stars":106804,"forks":14524,"observedAt":"2026-09-03T16:09:14.057Z","url":"https://github.com/google-gemini/gemini-cli","pushedAt":"2026-09-03T16:08:54Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/google-gemini/gemini-cli/main/README.md","observedAt":"2026-09-03T16:10:50.029Z","sha256":"bacf354f3f674d57679ebf7b42dd69311bb9ef14200e18ca703d82aba48bf833"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"google-gemini/gemini-cli:metadata","source_url":"https://github.com/google-gemini/gemini-cli","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Alanggenius%2Fdify%20repo%3AFlowiseAI%2FFlowise%20repo%3Asimstudioai%2Fsim%20repo%3Akestra-io%2Fkestra%20repo%3Aopenai%2Fcodex%20repo%3Agoogle-gemini%2Fgemini-cli%20repo%3Aanthropics%2Fclaude-code%20repo%3Abitwarden%2Fclients&per_page=100","stars":106804,"forks":14524,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:09:14.057Z"},{"source_type":"github","source_identifier":"google-gemini/gemini-cli:readme:bacf354f3f674d57679ebf7b42dd69311bb9ef14200e18ca703d82aba48bf833","source_url":"https://raw.githubusercontent.com/google-gemini/gemini-cli/main/README.md","raw_metadata":{"sha256":"bacf354f3f674d57679ebf7b42dd69311bb9ef14200e18ca703d82aba48bf833","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:50.029Z"}],"expected":"7d4aa1a7-bf99-4726-9420-3cfc979847a8"},{"identity":"repo:https://github.com/bitwarden/clients","slug":"bitwarden-63a07a69","name":"Bitwarden","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Kênh social cần được bảo vệ từ những mật khẩu không dùng lại.","description":"Repo này chứa các ứng dụng client Bitwarden, trừ ứng dụng mobile ở repo riêng. Windi chọn một mục bảo mật thiết thực cho creator quản lý nhiều tài khoản.","long_description":"ĐIỂM NỔI BẬT\n• Tiện ích trình duyệt lưu và điền thông tin đăng nhập.\n• Có trình tạo mật khẩu và kho lưu trữ để quản lý mục.\n• Có ứng dụng/tài liệu chính chủ và hướng dẫn khóa kho.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTạo mật khẩu riêng cho từng tài khoản công việc và bật bảo vệ đăng nhập theo hướng dẫn.\n\nBẮT ĐẦU\nLấy ứng dụng hoặc extension từ liên kết Bitwarden chính chủ, thiết lập tài khoản và phương án khôi phục an toàn.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông để lộ master password hay mã khôi phục trong video demo. Repo client không phải toàn bộ server; giấy phép/tính năng từng phần cần kiểm tra.","canonical_url":"https://github.com/bitwarden/clients","repository_url":"https://github.com/bitwarden/clients","documentation_url":"https://raw.githubusercontent.com/bitwarden/clients/main/README.md","owner_name":"bitwarden","license":"Có nhiều giấy phép theo phần; đối chiếu LICENSE và điều kiện gói, không gắn MIT mặc định.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":100,"categories":["tech"],"primaryCategory":"tech","selectionReason":"Phù hợp Tech & Bảo mật: Kênh social cần được bảo vệ từ những mật khẩu không dùng lại. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Kênh social cần được bảo vệ từ những mật khẩu không dùng lại.","highlights":["Tiện ích trình duyệt lưu và điền thông tin đăng nhập.","Có trình tạo mật khẩu và kho lưu trữ để quản lý mục.","Có ứng dụng/tài liệu chính chủ và hướng dẫn khóa kho."],"example":"Tạo mật khẩu riêng cho từng tài khoản công việc và bật bảo vệ đăng nhập theo hướng dẫn.","setup":"Lấy ứng dụng hoặc extension từ liên kết Bitwarden chính chủ, thiết lập tài khoản và phương án khôi phục an toàn.","limitations":"Không để lộ master password hay mã khôi phục trong video demo. Repo client không phải toàn bộ server; giấy phép/tính năng từng phần cần kiểm tra.","github":{"stars":13735,"forks":2007,"observedAt":"2026-09-03T16:09:14.057Z","url":"https://github.com/bitwarden/clients","pushedAt":"2026-09-03T16:09:12Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/bitwarden/clients/main/README.md","observedAt":"2026-09-03T16:10:53.041Z","sha256":"c5ea2d6804adf6756a7960464af86cfcbcbf4e0218377a86797dcd9cf1fa6db8"},"trending":null,"extraSources":["https://bitwarden.com/help/getting-started-browserext/"]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"bitwarden/clients:metadata","source_url":"https://github.com/bitwarden/clients","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Alanggenius%2Fdify%20repo%3AFlowiseAI%2FFlowise%20repo%3Asimstudioai%2Fsim%20repo%3Akestra-io%2Fkestra%20repo%3Aopenai%2Fcodex%20repo%3Agoogle-gemini%2Fgemini-cli%20repo%3Aanthropics%2Fclaude-code%20repo%3Abitwarden%2Fclients&per_page=100","stars":13735,"forks":2007,"license":"NOASSERTION"},"fetched_at":"2026-09-03T16:09:14.057Z"},{"source_type":"github","source_identifier":"bitwarden/clients:readme:c5ea2d6804adf6756a7960464af86cfcbcbf4e0218377a86797dcd9cf1fa6db8","source_url":"https://raw.githubusercontent.com/bitwarden/clients/main/README.md","raw_metadata":{"sha256":"c5ea2d6804adf6756a7960464af86cfcbcbf4e0218377a86797dcd9cf1fa6db8","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:53.041Z"},{"source_type":"manual","source_identifier":"https://bitwarden.com/help/getting-started-browserext/","source_url":"https://bitwarden.com/help/getting-started-browserext/","raw_metadata":{"relationship":"MAINTAINER","usage":"official_documentation"},"fetched_at":"2026-09-03T16:12:52.012Z"}],"expected":null}]'::jsonb) loop
  select * into existing from public.resources where external_identity=x->>'identity' for update;
  already:=found and existing.import_metadata->>'creatorImportHash'='70246f4c4a2f7774b985a83b1046397afb219b4521ac7e2ac8ae08790ad028cf';
  if already then continue; end if;
  if existing.id is not null and (existing.id::text is distinct from x->>'expected' or existing.editorial_revision<>0 or existing.status<>'CANDIDATE') then raise exception 'Candidate changed since snapshot: %',x->>'identity'; end if;
  if existing.id is null and x->>'expected' is not null then raise exception 'Candidate disappeared since snapshot'; end if;
  if existing.id is null then
    insert into public.resources(external_identity,slug,type,name,canonical_url) values(x->>'identity',x->>'slug',(x->>'type')::public.resource_type,x->>'name',x->>'canonical_url') returning id into rid;
  else rid:=existing.id; end if;
  update public.resources set name=x->>'name',type=(x->>'type')::public.resource_type,tagline=x->>'tagline',description=x->>'description',long_description=x->>'long_description',canonical_url=x->>'canonical_url',repository_url=x->>'repository_url',documentation_url=x->>'documentation_url',owner_name=x->>'owner_name',license=x->>'license',import_metadata=import_metadata||(x->'import_metadata')||jsonb_build_object('creatorImportHash','70246f4c4a2f7774b985a83b1046397afb219b4521ac7e2ac8ae08790ad028cf'),last_source_update_at=(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz,editorial_revision=editorial_revision+1,updated_at=now() where id=rid;
  for s in select value from jsonb_array_elements(x->'sources') loop
    insert into public.resource_sources(resource_id,source_type,source_identifier,source_url,raw_metadata,fetched_at) values(rid,s->>'source_type',s->>'source_identifier',s->>'source_url',s->'raw_metadata',(s->>'fetched_at')::timestamptz) on conflict(resource_id,source_type,source_identifier) do update set source_url=excluded.source_url,raw_metadata=excluded.raw_metadata,fetched_at=excluded.fetched_at;
  end loop;
  insert into public.resource_metric_snapshots(resource_id,source_type,metric_key,metric_value,captured_at) values(rid,'github','stars',(x#>>'{import_metadata,creatorCatalog,github,stars}')::numeric,(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz),(rid,'github','forks',(x#>>'{import_metadata,creatorCatalog,github,forks}')::numeric,(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz) on conflict do nothing;
  insert into public.resource_evidence_jobs(resource_id) values(rid) on conflict do nothing;
end loop;
end $creator_import$;
commit;
select count(*)::int as dossiers_written from public.resources where import_metadata->>'creatorImportHash'='70246f4c4a2f7774b985a83b1046397afb219b4521ac7e2ac8ae08790ad028cf';